$ for h in 31g 32g 33g; do java -Xmx$h -XX:+PrintFlagsFinal -version | grep UseCompressedOops; done
-Xmx31g   bool UseCompressedOops = true  {product lp64_product}
-Xmx32g   bool UseCompressedOops = false {product lp64_product}
-Xmx33g   bool UseCompressedOops = false {product lp64_product}

# 참조 필드 4개짜리 객체 100만 개를 만들어 할당 바이트를 센다 (12.2 의 방법)

$ java -Xmx256m -XX:+UseCompressedOops -cp out Oops
객체당 32 바이트  (총 32,000,000)

$ java -Xmx256m -XX:-UseCompressedOops -cp out Oops
객체당 48 바이트  (총 48,000,000)

# 같은 객체가 32 바이트와 48 바이트다 — 50% 더 크다.
